catalog_script_client.script:
function onSubmit() {
    //fetching date value from field 
    var dateValue = g_form.getValue('needed_datetime');

	//allowing submission if field is empty 
    if (!dateValue) {
        return true;
    }

    //replacing space with 'T' so browser can convert it properly
    var formattedDate = dateValue.replace(' ', 'T');

    //converting it into date only
    var selectedDateTime = new Date(formattedDate);

    //calculating today's date 
    var today = new Date();

    if (isNaN(selectedDateTime.getTime())) {
        g_form.addErrorMessage('Please enter a valid date and time.');
        return false;
    }

    //noe comparing field date to today's date if it is not in future do not let submitt the form 
    if (selectedDateTime <= today) {
        g_form.addErrorMessage('The preferred date and time must be in the future.');
        return false;
    }
}
